      async function ensureUsersTableUniqueIndex(db) {
        if (!db)
          return;
        try {
          await db.prepare(`
            DELETE FROM users
            WHERE rowid NOT IN (
              SELECT rowid FROM (
                SELECT rowid,
                       ROW_NUMBER() OVER (
                         PARTITION BY LOWER(TRIM(email))
                         ORDER BY is_onboarded DESC, email_verified DESC, rowid DESC
                       ) as rn
                FROM users
              )
              WHERE rn = 1
            )
          `).run();
        } catch (e) {
          try {
            await db.prepare(`
              DELETE FROM users
              WHERE rowid NOT IN (
                SELECT MAX(rowid) FROM users GROUP BY LOWER(TRIM(email))
              )
            `).run();
          } catch (e2) {
          }
        }
        try {
          await db.prepare(`
            CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email_unique ON users(LOWER(TRIM(email)))
          `).run();
        } catch (e) {
        }
      }
